def unique_jobs(rows):
    seen = {}
    counter = 0
    for r in rows:
        source = r.get('source', '')
        source_id = r.get('source_id')

        if source_id is None or source_id == '':
            # Each row with missing/None/empty source_id is its own group
            key = (None, counter)
            counter += 1
        else:
            key = (source, source_id)

        if key not in seen:
            seen[key] = r

    return list(seen.values())

